package com.ahmetemresanli.backend.controller.impl;
import com.ahmetemresanli.backend.controller.IAccountController;import com.ahmetemresanli.backend.dto.response.OperationResponse;import com.ahmetemresanli.backend.security.AccessControlService;import com.ahmetemresanli.backend.service.IAccountRecoveryService;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/account/email-verification")
public class AccountControllerImpl implements IAccountController {private final IAccountRecoveryService service;private final AccessControlService access;public AccountControllerImpl(IAccountRecoveryService service,AccessControlService access){this.service=service;this.access=access;}@Override @PostMapping("/primary") public ResponseEntity<OperationResponse> resendPrimaryVerification(){return ResponseEntity.ok(service.issueEmailVerification(access.currentUserId()));}@Override @PostMapping("/recovery") public ResponseEntity<OperationResponse> verifyRecoveryEmail(){return ResponseEntity.ok(service.issueRecoveryEmailVerification(access.currentUserId()));}}
